const edition = globalThis.makeSubjectEdition({"year":2022,"grade":"1-2","tasksFile":"zr_2122_zadanija_lq_1-2.pdf","answersFile":"reviewed-1-2.pdf","title":"Герои Отечества","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":30,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2022/1-2.json","reviewedKey":true}, [{"title":"Богатырь из Рязани","question":"О подвигах этого русского богатыря рассказывается в «Повести о разорении Рязани Батыем».","choices":["Илья Муромец","Микула Селянинович","Евпатий Коловрат","Никита Кожемяка"],"answer":2,"steps":["Герой возвращается в разорённую татарами Рязань и, по рассказу повести, собирает оставшихся в живых воинов.","В «Повести о разорении Рязани Батыем» его называют Евпатием Коловратом."]},{"title":"Три всадника","question":"Этот художник написал картину «Богатыри», на которой изображены главные герои русских былин: Добрыня Никитич, Илья Муромец и Алёша Попович.","choices":["В. И. Суриков","И. К. Айвазовский","И. Е. Репин","В. М. Васнецов"],"answer":3,"steps":["В центре полотна Илья Муромец заслоняет глаза ладонью, высматривая опасность.","Картину «Богатыри» с Ильёй, Добрыней и Алёшей написал Виктор Васнецов."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/2.webp","alt":"Три конных воина перед открытым полем","width":215,"height":140}},{"title":"Крещение Руси","question":"При этом князе в Х веке произошло крещение Руси.","choices":["Всеволод","Рюрик","Игорь","Владимир"],"answer":3,"steps":["Летописная традиция относит крещение киевлян к 988 году.","В это время в Киеве правил князь Владимир Святославич."]},{"title":"Поход в Сибирь","question":"Кто возглавил казачий поход за Урал против Сибирского ханства в конце XVI века?","choices":["Ермака Тимофеевича","Степана Разина","Емельяна Пугачева","Александра Невского"],"answer":0,"steps":["В конце XVI века отряд казаков перешёл Урал и вступил в земли Сибирского ханства.","Его возглавил Ермак Тимофеевич, с походом которого связывают важный этап продвижения Русского государства в Сибирь."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/4.webp","alt":"Историческая картина с лодками и сражением на реке","width":560,"height":261,"detailSrc":"assets/golden-fleece/2022/lessons/1-2/4-detail.webp"}},{"title":"Начало новой династии","question":"Первого русского царя из династии Романовых звали…","choices":["Алексей","Михаил","Николай","Пётр"],"answer":1,"steps":["В 1613 году после Смутного времени Земский собор избрал царём юного представителя рода Романовых.","Первого царя этой династии звали Михаил Фёдорович."]},{"title":"Монумент двум героям","question":"В центре этого города установлен памятник К. М. Минину и Д. М. Пожарскому, созданный И. П. Мартосом.","choices":["Москва","Санкт-Петербург","Ярославль","Смоленск"],"answer":0,"steps":["Иван Мартос изобразил руководителей ополчения, которое освободило Москву в 1612 году.","Подлинник памятника стоит на Красной площади в Москве, а в Нижнем Новгороде есть его более поздняя копия."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/6.webp","alt":"Бронзовый памятник с двумя фигурами","width":176,"height":235}},{"title":"Венчание в десять лет","question":"Этот царь, впоследствии прозванный Великим, был коронован в десять лет.","choices":["Алексей Михайлович","Фёдор Алексеевич","Пётр Алексеевич","Пётр Фёдорович"],"answer":2,"steps":["В 1682 году царями одновременно стали два брата — Иван и десятилетний Пётр.","Младший брат, Пётр Алексеевич, позднее вошёл в историю как Пётр Великий."]},{"title":"Книга полководца","question":"Кто из этих полководцев написал военные наставления, известные под названием «Наука побеждать»?","choices":["М. И. Кутузов","Пётр I","А. В. Суворов","Александр Невский"],"answer":2,"steps":["Название «Наука побеждать» закрепилось за наставлениями российского полководца XVIII века.","Автор наставлений — Александр Васильевич Суворов."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/8.webp","alt":"Портрет пожилого человека в светлом мундире","width":156,"height":202}},{"title":"Окно в Европу","question":"Принято считать, что этот российский император «прорубил окно в Европу».","choices":["Николай I","Павел I","Пётр I","Александр II"],"answer":2,"steps":["Образ окна связан с выходом России к Балтийскому морю и основанием Санкт-Петербурга.","Город в устье Невы заложил Пётр I."]},{"title":"Герои на постаменте","question":"Скульптурная композиция, посвящённая этому писателю, установлена в Санкт-Петербурге в Летнем саду.","choices":["Л. Н. Толстой","Н. В. Гоголь","И. А. Крылов","А. С. Пушкин"],"answer":2,"steps":["На памятнике в Летнем саду писатель сидит с книгой, а на постаменте изображены звери из его произведений.","Это герои басен Ивана Андреевича Крылова."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/10.webp","alt":"Сидящая фигура на постаменте в саду","width":186,"height":211}},{"title":"Механик-самоучка","question":"Среди изобретений этого механика-самоучки особо известны лифт, фонарь-прожектор и трёхколёсная самокатка — прообраз автомобиля.","choices":["М. В. Ломоносов","И. П. Кулибин","Д. И. Менделеев","А. К. Нартов"],"answer":1,"steps":["Фонарь с отражателем, подъёмный механизм для дворца и самокатная повозка относятся к разным областям техники.","Все три проекта связаны с русским механиком Иваном Петровичем Кулибиным."]},{"title":"Дорога за знаниями","question":"Какой будущий учёный в юности добрался до Москвы с рыбным обозом, чтобы продолжить обучение?","choices":["М. В. Ломоносов","И. П. Кулибин","Д. И. Менделеев","А. Д. Сахаров"],"answer":0,"steps":["Юноша из окрестностей Холмогор отправился с обозом в Москву и поступил в Славяно-греко-латинскую академию.","Так начинался путь в науку Михаила Васильевича Ломоносова."]},{"title":"Родной город поэта","question":"В этом городе родился величайший русский поэт А. С. Пушкин.","choices":["Санкт-Петербург","Москва","Царское Село","Псков"],"answer":1,"steps":["Александр Пушкин родился в 1799 году и был крещён в Богоявленской церкви в Елохове.","Елохово находится в Москве, а Царское Село связано уже с лицейскими годами поэта."]},{"title":"Письмо запорожцев","question":"На картине И. Е. Репина запорожские казаки пишут письмо…","choices":["крымскому хану","Соловью-разбойнику","русскому князю","турецкому султану"],"answer":3,"steps":["В центре картины Репина писарь заносит на бумагу ответ, который диктуют смеющиеся казаки.","Полное название сюжета — «Запорожцы пишут письмо турецкому султану»."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/14.webp","alt":"Картина с казаками за столом","width":560,"height":331,"detailSrc":"assets/golden-fleece/2022/lessons/1-2/14-detail.webp"}},{"title":"Командующий при Бородине","question":"В Бородинском сражении русской армией командовал…","choices":["М. И. Кутузов","А. В. Суворов","Г. К. Жуков","Ф. Ф. Ушаков"],"answer":0,"steps":["К моменту Бородинского сражения в 1812 году русские армии находились под общим руководством одного главнокомандующего.","Им был Михаил Илларионович Кутузов."]},{"title":"Рассказ солдата","question":"В этом стихотворении М. Ю. Лермонтова простой солдат так описывает один из эпизодов сражения:\n\nВот затрещали барабаны —\nИ отступили бусурманы.","choices":["Бой","Кинжал","Бородино","Утёс"],"answer":2,"steps":["Стихотворение начинается с вопроса «Скажи-ка, дядя…».","Дальше старый солдат рассказывает о сражении у села Бородина, поэтому произведение Лермонтова называется «Бородино»."]},{"title":"Поэт и партизан","question":"Этот поэт во время Отечественной войны 1812 года командовал партизанским отрядом.","choices":["М. Ю. Лермонтов","А. С. Пушкин","А. С. Грибоедов","Д. В. Давыдов"],"answer":3,"steps":["Этот офицер-гусар писал стихи и в 1812 году командовал отрядом, действовавшим в тылу армии Наполеона.","Поэт-партизан — Денис Васильевич Давыдов."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/17.webp","alt":"Портрет мужчины в гусарском мундире","width":179,"height":207}},{"title":"Галерея в Эрмитаже","question":"В Военной галерее Эрмитажа собраны портреты героев этой войны.","choices":["Великая Северная","Отечественная 1812 года","Первая мировая","Великая Отечественная"],"answer":1,"steps":["В Зимнем дворце есть зал с портретами российских генералов, воевавших с Наполеоном.","Он называется Военной галереей 1812 года и посвящён героям Отечественной войны 1812 года."]},{"title":"Порядок элементов","question":"Этот учёный разработал периодическую систему химических элементов.","choices":["М. В. Ломоносов","Д. И. Менделеев","Н. И. Лобачевский","И. П. Павлов"],"answer":1,"steps":["Учёный расположил химические элементы так, чтобы обнаруживалась повторяемость их свойств, и оставил места для ещё неизвестных элементов.","Периодическую систему предложил Дмитрий Иванович Менделеев."]},{"title":"Два шлюпа","question":"Какое географическое открытие сделали моряки экспедиции на шлюпах «Восток» и «Мирный» в 1820 году?","choices":["Пролив между Камчаткой и Японией","Антарктида","Бухта Севастополя","Северный морской путь"],"answer":1,"steps":["Шлюпами «Восток» и «Мирный» командовали Фаддей Беллинсгаузен и Михаил Лазарев. Они вели экспедицию далеко на юг.","В январе 1820 года моряки приблизились к побережью и увидели материковый лёд. Так был обнаружен южный материк — Антарктида."],"references":["https://www.prlib.ru/history/618985","https://www.prlib.ru/node/1159789","https://www.prlib.ru/item/407322"],"taskUrl":"https://runodog.ru/ZR_2122/zr_2122_zadanija_lq_1-2.pdf#page=2","adaptation":"Редакция вопроса проверена по первоисточникам.","figure":{"src":"assets/golden-fleece/2022/lessons/1-2/20.webp","alt":"Два парусных судна среди волн и льда","width":237,"height":148}},{"title":"Малахов курган","question":"Одним из эпизодов этой войны стала героическая оборона Малахова кургана.","choices":["Отечественная 1812 года","Крымская","Первая мировая","Русско-персидская"],"answer":1,"steps":["Курган находится в Севастополе и был важным местом обороны города в 1854–1855 годах.","Эти даты относятся к Крымской войне."]},{"title":"Голос певца","question":"Выдающийся русский певец, изображённый на картине Б. М. Кустодиева, был…","choices":["контральто","тенором","баритоном","басом"],"answer":3,"steps":["На портрете Бориса Кустодиева — Фёдор Шаляпин, знаменитый исполнитель партии Бориса Годунова.","Его низкий мужской голос называется басом."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/22.webp","alt":"Портрет человека в меховой шубе","width":176,"height":219}},{"title":"Монумент на кургане","question":"В этом городе находится монумент «Родина-мать зовет!», посвящённый героической обороне Сталинграда во время Великой Отечественной войны.","choices":["Санкт-Петербург","Москва","Волгоград","Смоленск"],"answer":2,"steps":["Скульптура «Родина-мать зовёт!» стоит на Мамаевом кургане в бывшем Сталинграде.","Современное название города — Волгоград."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/23.webp","alt":"Высокая фигура женщины с поднятым мечом","width":180,"height":287}},{"title":"Первый полёт человека","question":"Этот человек совершил первый в мире космический полёт.","choices":["Ю. А. Гагарин","А. А. Леонов","Г. М. Гречко","В. В. Терешкова"],"answer":0,"steps":["12 апреля 1961 года корабль «Восток-1» совершил орбитальный полёт с человеком на борту.","Первым космонавтом стал Юрий Алексеевич Гагарин."]},{"title":"Позывной на орбите","question":"Позывным В. В. Терешковой, первой в мире женщины-космонавта, был…","choices":["Белка","Стрелка","Чайка","Кедр"],"answer":2,"steps":["Валентина Терешкова летала в 1963 году на корабле «Восток-6».","Во время радиосвязи она пользовалась позывным «Чайка»."]},{"title":"Монумент рабочему и воину","question":"Монумент «Тыл — фронту» в Магнитогорске воздвигнут в память о…","choices":["Ледовом побоище","Куликовской битве","Первой мировой войне","Великой Отечественной войне"],"answer":3,"steps":["В магнитогорской скульптурной группе рабочий передаёт меч воину.","Так показан труд людей в тылу во время Великой Отечественной войны."],"figure":{"src":"assets/golden-fleece/2022/lessons/1-2/26.webp","alt":"Две фигуры поднимают меч","width":152,"height":207}},{"title":"Голос Винни-Пуха","question":"Какой актёр озвучил Винни-Пуха в советских мультфильмах Фёдора Хитрука?","choices":["В. Б. Ливанов","Е. П. Леонов","Ю. В. Никулин","А. А. Миронов"],"answer":1,"steps":["В советских мультфильмах Фёдора Хитрука медвежонок говорит узнаваемым голосом с особой интонацией.","Озвучивал Винни-Пуха Евгений Павлович Леонов."]},{"title":"Название яхты","question":"Кругосветное путешествие капитана Врунгеля, героя повести А. С. Некрасова и советского мультфильма, начинается на корабле, при строительстве названном …","choices":["Виктория","Аврора","Победа","Беда"],"answer":2,"steps":["До старта яхта капитана Врунгеля носит имя из шести букв.","После потери первых двух букв «Победа» превращается в «Беду»."]},{"title":"Восстание в сказке","question":"Сказка Ю. К. Олеши о восстании, поднятом бедняками против богачей, называется …","choices":["Три богатыря","Три толстяка","Два капитана","Военная тайна"],"answer":1,"steps":["В сказке Юрия Олеши действуют оружейник Просперо, гимнаст Тибул и девочка Суок.","Они выступают против правителей, по которым книга названа «Три толстяка»."]},{"title":"Троица из кинокомедии","question":"В советском мультфильме «Бременские музыканты» прообразом трёх разбойников послужили герои фильма «Кавказская пленница», прозвища которых …","choices":["Фукс, Бандитто и Гангстеритто","Алёша, Илья и Добрыня","Трус, Балбес и Бывалый","Али-Баба, Хмырь и Косой"],"answer":2,"steps":["Облик мультяшных разбойников напоминает персонажей, которых играли Георгий Вицин, Юрий Никулин и Евгений Моргунов.","Знаменитые экранные прозвища этой троицы — Трус, Балбес и Бывалый."]}]);
